mapper.select:
SELECT a.id, a.title, a.slug, a.summary, a.cover_image, a.category_id, c.name AS category_name, a.status, a.view_count, a.published_at, a.created_at, a.updated_at, a.deleted FROM article a LEFT JOIN category c ON c.id = a.category_id
a.deleted = false AND a.status = #{status} AND a.category_id = #{categoryId} AND a.title ILIKE '%' || #{keyword} || '%'
ORDER BY a.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM article a

    a.deleted = false
    AND a.status = #{status}
    AND a.category_id = #{categoryId}
    AND a.title ILIKE '%' || #{keyword} || '%'

SELECT DISTINCT a.id, a.title, a.slug, a.summary, a.cover_image, a.category_id, c.name AS category_name, a.status, a.view_count, a.published_at, a.created_at, a.updated_at, a.deleted FROM article a LEFT JOIN category c ON c.id = a.category_id
JOIN article_tag at_ ON at_.article_id = a.id AND at_.tag_id = #{tagId}
a.deleted = false AND a.status = 'PUBLISHED' AND a.category_id = #{categoryId} AND (a.title ILIKE '%' || #{keyword} || '%' OR a.summary ILIKE '%' || #{keyword} || '%')
ORDER BY a.published_at DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(DISTINCT a.id) FROM article a
JOIN article_tag at_ ON at_.article_id = a.id AND at_.tag_id = #{tagId}
a.deleted = false AND a.status = 'PUBLISHED' AND a.category_id = #{categoryId} AND (a.title ILIKE '%' || #{keyword} || '%' OR a.summary ILIKE '%' || #{keyword} || '%')

SELECT at_.article_id AS articleId, t.id AS tagId, t.name AS tagName FROM article_tag at_ JOIN tag t ON t.id = at_.tag_id WHERE at_.article_id IN
#{aid}
ORDER BY at_.article_id, t.id
